'use strict';
const $=id=>document.getElementById(id),KEY=Profiles.key('training'),names=['词汇与语境','听力与听写','翻译与写作','回顾与复习'];
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db={version:1,round:0,words:{},history:[],session:null},storageOK=true,blocked=false;
try{const raw=localStorage.getItem(KEY);if(raw)db=Core.validate(JSON.parse(raw));}catch(e){blocked=true;storageOK=false;}
function makeSession(){const next=Core.session(WORDS,db);Library.pin(next);return next;}
if(!db.session)db.session=makeSession();
if(!db.session.material){if(Object.keys(db.session.answers).length||Object.keys(db.session.graded).length){const old=LESSONS[db.session.lesson];db.session.material={...old,id:'legacy-'+db.session.lesson,theme:'旧版原创',publisher:'原创情境',sourceUrl:'',sourcePublished:'2026-10-08',checkedAt:'2026-10-08',kind:'原创情境',note:'保留旧轮次原题',paragraph:old.chinese,paragraphTranslation:old.translation,keywords:[]};}else Library.pin(db.session);}
let s=db.session,last=performance.now(),timer=null,installPrompt=null,audio=null,tabOwned=true;
const bc='BroadcastChannel' in window?new BroadcastChannel('cet6-training-'+Profiles.active):null;
bc?.postMessage('claim');if(bc)bc.onmessage=e=>{if(e.data==='claim'){pause();tabOwned=false;storageOK=false;blocked=true;$('toggle').disabled=true;toast('另一标签页已接管训练，请在此页刷新后再学习。');}};
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',4500);}
function save(){if(blocked)return false;db.session=s;db.updatedAt=Date.now();try{localStorage.setItem(KEY,JSON.stringify(db));storageOK=true;$('save').textContent='已保存 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'});return true;}catch(e){storageOK=false;$('save').textContent='保存失败，请导出备份';return false;}}
function clock(ms){const t=Math.ceil(Math.max(0,ms)/1000);return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');}
function clocks(){const remaining=Core.durations[s.stage]-s.elapsed[s.stage];$('total').textContent=clock(1200000-s.elapsed.reduce((a,b)=>a+b,0));$('remaining').textContent=clock(remaining);$('status').textContent=s.finished?'本轮已结束':s.running?'正在专注 · '+names[s.stage]:s.elapsed.some(x=>x)?'已暂停 · 随时继续':'准备开始';$('toggle').textContent=s.finished?'本轮已结束':s.running?'暂停训练':s.elapsed.some(x=>x)?'继续训练':'开始训练';$('toggle').disabled=s.finished||blocked;}
function tick(){const now=performance.now(),delta=now-last;last=now;if(s.running){const stage=s.stage;Core.advance(s,delta);if(stage!==s.stage||s.finished){stopAudio();if(s.finished)archive();render();}save();}clocks();}
function stopAudio(){Pronunciation.stop();if(audio){s.audioTime=audio.currentTime||0;audio.pause();}}
function pause(){if(s.running){tick();s.running=false;}stopAudio();save();clocks();}
function archive(){if(db.history.some(h=>h.id===s.id))return;db.history.push({id:s.id,lesson:s.lesson,material:s.material,completedAt:Date.now(),elapsed:[...s.elapsed],graded:{...s.graded},answers:{...s.answers}});db.history=db.history.slice(-500);}
function nextStage(){tick();stopAudio();if(s.stage===3){s.finished=true;s.running=false;archive();}else{s.stage++;}save();render();}
function bindDraft(id,key){const el=$(id);if(!el)return;el.value=s.answers[key]??'';el.addEventListener('input',()=>{s.answers[key]=el.value;s.checked[key]=false;save();if(id==='writing')$('wc').textContent=CoreCount(el.value);const feedback=$('feedback-'+key);if(feedback)feedback.hidden=true;});}
function CoreCount(v){return v.trim()?v.trim().split(/\s+/).length:0;}
function taskButton(){return `<div class="row spaced"><span class="meta">时间到会自动切换；也可提前进入下一阶段。</span><button id="nextstage">${s.stage===3?'结束本轮':'下一阶段'}</button></div>`;}
function render(){stopAudio();audio=null;$('phaseLabel').textContent='PART '+(s.stage+1)+' / 4';$('phaseTitle').textContent=names[s.stage];$('stages').innerHTML=names.map((n,i)=>`<button data-stage="${i}" class="${s.stage===i?'active':''}" ${s.finished?'disabled':''} ${s.stage===i?'aria-current="step"':''}><span class="step">0${i+1}</span><span>${n}<small>${[7,7,4,2][i]} 分钟${s.elapsed[i]>=Core.durations[i]?' · 已计满':''}</small></span></button>`).join('');$('stages').querySelectorAll('button').forEach(b=>b.onclick=()=>{tick();stopAudio();s.stage=Number(b.dataset.stage);save();render();});if(s.finished){renderReview(true);}else if(s.stage===0)renderWords();else if(s.stage===1)renderListening();else if(s.stage===2)renderWriting();else renderReview(false);const next=$('nextstage');if(next)next.onclick=nextStage;clocks();}
function renderWords(){const item=s.queue[s.index];if(!item){renderContext();return;}const w=WORDS[item.id],rated=Object.keys(s.graded).length,rev=s.queue.filter(x=>x.kind==='review').length,fresh=s.queue.filter(x=>x.kind==='new').length;
 $('activity').innerHTML=`<div class="row spaced"><span class="badge">${item.kind==='review'?'到期复习':item.kind==='new'?'新词':'巩固练习'}</span><span class="meta">${s.index+1} / ${s.queue.length} · 复习 ${rev} / 新词 ${fresh}</span></div><h3 class="word">${esc(w.word)}</h3><span class="meta">${esc(w.phonetic||'')} · ${esc(w.theme||'编辑基础词')}</span>${Pronunciation.html()}<p>先回忆词义，再看答案。</p>${w.example?`<div class="example">${esc(w.example)}</div>`:'<p class="meta">此词暂未编写离线语境例句，可联网查询，或写一句自己的表达。</p>'}<div class="row"><button id="lookupExample">联网查例句</button></div><div id="onlineExample">${s.answers['example-'+w.id]?`<div class="example">${esc(s.answers['example-'+w.id])}</div><p class="meta">之前保存的联网例句 · Free Dictionary API</p>`:''}</div><details><summary>用这个词写一句自己的表达</summary><label for="wordSentence">你的语境句</label><textarea id="wordSentence" maxlength="20000"></textarea></details>${s.revealed?`<div class="answer"><b>${esc(w.meaning)}</b><br>${esc(w.translation)}${w.collocation?`<br>搭配：${esc(w.collocation)}<br>语境改述：${esc(w.synonym)}`:''}</div><p class="meta">根据真实回忆情况，安排下次复习。</p><div class="row"><button data-grade="0">忘记了 · 10 分钟后</button><button data-grade="1">有点模糊 · 明天</button><button data-grade="2" class="primary">记住了</button></div>`:'<button id="reveal" class="primary">显示词义</button>'}<div class="progress"><div style="width:${rated/s.queue.length*100}%"></div></div><div class="row"><button id="context">进入语境练习</button></div>${taskButton()}`;
 Pronunciation.bind(w.word);bindDraft('wordSentence','sentence-'+w.id);if($('lookupExample'))$('lookupExample').onclick=()=>lookupExample(w);if($('reveal'))$('reveal').onclick=()=>{s.revealed=true;save();render();};document.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{const grade=Number(b.dataset.grade);db.words[w.id]=Core.schedule(db.words[w.id],grade,Date.now());s.graded[w.id]=grade;s.index++;s.revealed=false;save();render();});$('context').onclick=()=>{s.answers.contextMode=true;save();renderContext();$('nextstage').onclick=nextStage;};if(s.answers.contextMode){renderContext();}
}
function renderContext(){const targets=s.queue.filter(x=>x.kind==='new');const chosen=(targets.length?targets:s.queue).slice(0,3).map(x=>WORDS[x.id]);if(!chosen.length){$('activity').innerHTML='<p>当前没有词汇可练习。</p>'+taskButton();return;}
const i=Math.min(s.clozeIndex,chosen.length-1),w=chosen[i],key='cloze'+i,checked=s.checked[key],correct=Core.score(s.answers[key]||'',w.word)===100;
$('activity').innerHTML=`<span class="badge">语境练习 ${i+1} / ${chosen.length}</span><h3 style="margin-top:18px">让新词在句子里留下来</h3><p>根据中文提示填入本轮词汇。</p><div class="example">${w.example?esc(w.example.replace(new RegExp(w.word,'i'),'________')):'根据释义回忆英文：'+esc(w.meaning)}<br><span class="meta">${esc(w.translation||'暂无离线例句，本题为词义回忆')}</span></div><label for="cloze">填写一个英文单词</label><input id="cloze" type="text" autocomplete="off"><div class="row"><button id="checkCloze" class="primary">核对答案</button>${checked?'<button id="nextCloze">下一句</button>':''}<button id="backWords">返回词卡</button></div>${checked?`<div class="answer ${correct?'':'error'}">${correct?'正确':'再记一次'} · ${w.word}<br>${w.meaning}</div>`:''}${taskButton()}`;
bindDraft('cloze',key);$('cloze').addEventListener('input',()=>{if($('nextCloze'))$('nextCloze').disabled=true;});$('checkCloze').onclick=()=>{s.checked[key]=true;save();renderContext();$('nextstage').onclick=nextStage;};if($('nextCloze'))$('nextCloze').onclick=()=>{if(i<chosen.length-1){s.clozeIndex++;save();renderContext();$('nextstage').onclick=nextStage;}else{toast('语境练习完成，进入听力。');nextStage();}};$('backWords').onclick=()=>{s.answers.contextMode=false;save();render();};}
function renderListening(){const l=LESSONS[s.lesson],checked=s.checked.dictation,chosen=s.answers.synonym;
$('activity').innerHTML=`<span class="badge">${l.title} · 原创合成音频</span><p>① 听全文抓大意　② 播放目标句听写　③ 找到同义表达</p><audio id="audio" controls preload="metadata" src="${s.answers.clip==='sentence'?l.audio.replace('.wav','-sentence.wav'):l.audio}"></audio><div class="row"><label for="speed">播放速度</label><select id="speed" style="width:auto"><option value="0.8">0.8×</option><option value="1">1×</option><option value="1.2">1.2×</option></select><button id="fullAudio">播放全文</button><button id="sentence">播放听写句</button></div><label for="dictation">听写目标句（可反复播放）</label><textarea id="dictation" placeholder="写下你听到的英文句子…" maxlength="20000"></textarea><button id="checkDict" class="primary">核对听写</button>${checked?`<div id="feedback-dictation" class="answer">词序匹配 ${Core.score(s.answers.dictation||'',l.dictation)}% · 辅助反馈<br>${l.dictation}</div>`:''}<h3 style="margin-top:25px">同义替换</h3><p>${l.question}</p><div id="choices">${l.options.map((o,i)=>`<label class="example"><input type="radio" name="synonym" value="${i}" ${chosen===String(i)?'checked':''}> ${o}</label>`).join('')}</div><button id="checkSyn">核对选择</button>${s.checked.synonym?`<div class="answer ${Number(chosen)===l.correct?'':'error'}">${Number(chosen)===l.correct?'正确':'正确答案：'+l.options[l.correct]}<br>${l.explanation}</div>`:''}<details id="transcript"><summary>查看全文与表达</summary><p>${l.script}</p></details>${taskButton()}`;
bindDraft('dictation','dictation');audio=$('audio');audio.addEventListener('loadedmetadata',()=>{audio.currentTime=Math.min(s.audioTime,audio.duration||0);audio.playbackRate=Number(s.answers.speed||1);});audio.addEventListener('timeupdate',()=>{s.audioTime=audio.currentTime;save();});audio.addEventListener('play',()=>{if(!s.running){audio.pause();toast('先开始或继续训练，再播放音频。');}});audio.addEventListener('error',()=>toast('音频未加载，请首次联网打开并等待离线缓存。'));
$('speed').value=s.answers.speed||'1';$('speed').onchange=e=>{s.answers.speed=e.target.value;audio.playbackRate=Number(e.target.value);save();};$('sentence').onclick=()=>{if(!s.running){toast('请先开始训练。');return;}s.audioTime=0;s.answers.clip='sentence';save();audio.src=l.audio.replace('.wav','-sentence.wav');audio.play().catch(()=>toast('请点击音频播放按钮重试。'));};$('fullAudio').onclick=()=>{if(!s.running){toast('请先开始训练。');return;}s.audioTime=0;s.answers.clip='full';save();audio.src=l.audio;audio.play().catch(()=>toast('请点击音频播放按钮重试。'));};$('checkDict').onclick=()=>{s.checked.dictation=true;save();render();};document.querySelectorAll('[name=synonym]').forEach(el=>el.onchange=()=>{s.answers.synonym=el.value;s.checked.synonym=false;save();});$('checkSyn').onclick=()=>{if(s.answers.synonym===undefined){toast('请先选择一个答案。');return;}s.checked.synonym=true;save();render();};}
function renderWriting(){const l=s.material||Library.pin(s);$('activity').innerHTML=`<span class="badge">2 分钟翻译 + 2 分钟短写 · ${esc(l.title)}</span>${Library.sourceHTML(l)}<h3 style="margin-top:18px">把一句话译准确</h3><div class="example">${esc(l.chinese)}</div><label for="translation">你的英文翻译</label><textarea id="translation" maxlength="20000" placeholder="先写自己的版本…"></textarea><button id="checkTrans">查看参考译文</button>${s.checked.translation?`<div id="feedback-translation" class="answer">${esc(l.translation)}<br><b>可迁移句式：</b>${esc(l.pattern)}</div>`:''}<h3 style="margin-top:24px">再写一段自己的观点</h3><p>${esc(l.prompt)}</p><label for="writing">你的短写 · <span id="wc">${CoreCount(s.answers.writing||'')}</span> 词</label><textarea id="writing" maxlength="20000" placeholder="观点 → 例子 → 结果"></textarea><button id="checkWrite">查看范例与自检</button>${s.checked.writing?`<div id="feedback-writing" class="answer">${esc(l.sample)}</div><ul class="checks">${l.checks.map((c,i)=>`<li><label><input type="checkbox" data-self="${i}" ${s.answers['self'+i]?'checked':''}> ${esc(c)}</label></li>`).join('')}</ul><p class="meta">参考表达用于自检，不是考试评分。</p>`:''}${taskButton()}`;bindDraft('translation','translation');bindDraft('writing','writing');$('checkTrans').onclick=()=>{s.checked.translation=true;save();render();};$('checkWrite').onclick=()=>{s.checked.writing=true;save();render();};document.querySelectorAll('[data-self]').forEach(el=>el.onchange=()=>{s.answers['self'+el.dataset.self]=el.checked;save();});}
function renderReview(finished){const forgotten=Object.keys(s.graded).filter(id=>s.graded[id]<2),learned=Object.keys(db.words).length,due=Object.values(db.words).filter(x=>x.due<=Date.now()).length;const l=s.material||Library.pin(s);$('activity').innerHTML=`<span class="badge">${finished?'本轮已归档':'最后两分钟，回忆一下'}</span><h3 style="margin-top:18px">今天留下了什么？</h3><div class="metric"><div><strong>${Object.keys(s.graded).length}</strong>本轮词卡</div><div><strong>${learned}</strong>累计词汇</div><div><strong>${due}</strong>当前到期</div></div><h3 style="margin-top:22px">需要再见一面的词</h3>${forgotten.length?`<ul class="checks">${forgotten.map(id=>`<li><b>${WORDS[id].word}</b> · ${WORDS[id].meaning}<br><small>下次复习：${new Date(db.words[id].due).toLocaleString('zh-CN')}</small></li>`).join('')}</ul>`:'<p>本轮没有标记薄弱词；未完成词卡会留给下一轮。</p>'}<div class="example"><b>带走一个表达</b><br>${esc(l.pattern)}</div><label for="reflection">不用看答案，写下一个新词、一个表达或下次目标</label><textarea id="reflection" maxlength="20000" placeholder="例如：把 accessible 用在自己的句子中…"></textarea>${finished?`<p class="meta">本轮计时 ${clock(s.elapsed.reduce((a,b)=>a+b,0))}。提前结束也会保留所有作答。</p><button id="startNew" class="primary">开始新一轮</button>`:taskButton()}`;bindDraft('reflection','reflection');if($('startNew'))$('startNew').onclick=newRound;}
async function newRound(){pause();if(!s.finished&& (s.elapsed.some(x=>x)||Object.keys(s.answers).length||Object.keys(s.graded).length)&&!await AppDialog.confirm('结束当前轮次并开始新一轮？已有作答会保留在备份历史中。'))return;archive();db.round++;s=makeSession();save();render();}
$('toggle').onclick=()=>{if(s.running)pause();else{s.running=true;last=performance.now();save();clocks();}};$('new').onclick=newRound;
$('export').onclick=()=>{pause();const blob=new Blob([JSON.stringify({...db,library:Library.backup()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cet6-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{pause();const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('文件超过 5 MB');const imported=Core.validate(JSON.parse(await file.text()));if(imported.library)Library.validate(imported.library.pack);if(imported.session?.material)Library.validate({version:1,materials:[imported.session.material]});if(!await AppDialog.confirm('导入会替换本设备的学习记录。建议先导出当前备份。继续导入？'))return;if(imported.library)Library.restore(imported.library);db=imported;s=db.session||makeSession();blocked=false;tabOwned=true;bc?.postMessage('claim');save();render();toast('已导入，点击继续训练。');}catch(err){toast('无法导入：'+err.message);}finally{e.target.value='';}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();else {last=performance.now();if(navigator.onLine)Library.refresh();}});window.addEventListener('pagehide',pause);window.addEventListener('beforeunload',pause);
function online(){$('network').textContent=navigator.onLine?'本地学习 · 在线':'本地学习 · 离线';}window.addEventListener('online',()=>{online();Library.refresh();});window.addEventListener('offline',online);online();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true;}};
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(async reg=>{const cache=await caches.open('cet6-v9');const ready=await cache.match(new URL('./offline-ready',location.href));$('offline').textContent=ready?'离线资源已就绪 · 音频也可离线播放':'离线缓存正在准备，稍后刷新检查。';navigator.serviceWorker.addEventListener('message',e=>{if(e.data==='offline-ready')$('offline').textContent='离线资源已就绪 · 音频也可离线播放';});}).catch(()=>$('offline').textContent='离线缓存不可用：请通过 HTTPS 或 localhost 打开，避免无痕模式。');else $('offline').textContent='当前浏览器不支持离线安装。';
render();if(blocked){$('save').textContent='本地记录损坏或被其他标签页接管；请导入备份';toast('读取本地记录失败。原记录未覆盖，可导入有效备份。');}else save();setInterval(tick,1000);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_training_progress',description:'读取当前训练阶段、计时和已完成词卡，不改变学习记录。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('不接受参数');return {stage:names[s.stage],remaining:Core.durations[s.stage]-s.elapsed[s.stage],running:s.running,finished:s.finished,graded:Object.keys(s.graded).length};}})).catch(()=>{});}catch(e){}}

// A fresh remote lookup is optional. Never label a missing example as completed.
async function lookupExample(w){const node=$('onlineExample');node.textContent='正在查询公开英语词典…';try{const response=await fetch('https://api.dictionaryapi.dev/api/v2/entries/en/'+encodeURIComponent(w.word),{signal:AbortSignal.timeout(7000)});if(!response.ok)throw Error('未找到可用条目');const data=await response.json();const items=Array.isArray(data)?data:[];let example='';for(const entry of items)for(const meaning of entry.meanings||[])for(const definition of meaning.definitions||[])if(!example&&typeof definition.example==='string')example=definition.example;if(!example)throw Error('此词没有公开例句');if(!$('onlineExample')||s.queue[s.index]?.id!==w.id)return;s.answers['example-'+w.id]=example.slice(0,1000);save();node.innerHTML='<div class="example">'+esc(example.slice(0,1000))+'</div><p class="meta">来源：Free Dictionary API（公开词典例句，非真题） · '+esc(items[0]?.license?.name||'以返回数据授权为准')+'</p>';}catch(e){node.textContent='联网例句暂不可用：'+e.message+'。离线词义学习不受影响。';}}
function renderWordSearch(){const q=$('wordSearch').value.trim().toLowerCase();const limit=db.wordLimit||4000;const results=WORDS.filter(w=>w.id<limit&&(!q||w.word.toLowerCase().includes(q)||w.meaning.includes(q))).slice(0,25);$('wordResults').innerHTML=results.map(w=>'<div class="vocab-row"><b>'+esc(w.word)+'</b> <span class="meta">'+esc(w.phonetic||'')+'</span><br>'+esc(w.meaning)+'<br><small class="muted">'+esc(w.source||'原创编辑词汇')+'</small></div>').join('')||'<p>没有匹配词条。</p>';}
$('wordMode').value=(db.wordLimit||4000)===4000?'4000':'all';$('wordMode').onchange=()=>{db.wordLimit=$('wordMode').value==='all'?WORDS.length:4000;save();renderWordSearch();toast('词库选择已保存，将用于新一轮训练；当前轮次保持原题。');};$('wordSearch').oninput=renderWordSearch;$('vocabTotal').textContent=WORDS.length+' 个独立词条';$('vocabDescription').textContent='源词库 '+VOCAB_META.upstreamCount+' 词（'+VOCAB_META.upstreamUpdatedAt+'），加上编辑补充后共 '+WORDS.length+' 词。默认 4,000 词，切换全量可学习其余词条。每次查询显示最多 25 条。';renderWordSearch();AppDialog.bind();Profiles.render();Library.render();Library.refresh();setInterval(()=>{if(!document.hidden&&navigator.onLine)Library.refresh();},300000);

